// Jenkins pipeline for Gkeyll, built/run on our own persistent machines
// (see ci/jenkins/README.md for how the Jenkins job driving this is set up).
//
// Unlike .github/workflows/mac_build.yml (ephemeral GitHub-hosted runner,
// build-only), this pipeline runs on persistent nodes that already have
// gkylsoft/ installed, and actually executes the unit tests.

def buildAndTest = {
    stage('Environment') {
        sh 'printenv'
    }
    stage('Unit tests') {
        sh 'make -j3 check'
    }
    stage('Regression build') {
        sh 'make -j3 regression'
    }
}

pipeline {
    agent none

    options {
        disableConcurrentBuilds(abortPrevious: true)
    }

    stages {
        stage('Build & Test') {
            parallel(
                'mana-node': {
                    node('mana-node') {
                        checkout scm
                        buildAndTest()
                    }
                }
                // Add the workstation here once it is registered as a Jenkins
                // agent, e.g.:
                // 'workstation-node': {
                //     node('workstation-node') {
                //         checkout scm
                //         buildAndTest()
                //     }
                // }
            )
        }
    }

    post {
        always {
            archiveArtifacts allowEmptyArchive: true, artifacts: 'build/**/*.log'
        }
    }
}

